const PREFIXES=['snowvalley-','yunxiu-'];
export const allowedKey=k=>typeof k==='string'&&PREFIXES.some(p=>k.startsWith(p));
const DB='snowvalley-terrain-backups';
const request=r=>new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
const done=tx=>new Promise((resolve,reject)=>{tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('数据库事务中止'));});
async function openDB(){const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('drafts'))r.result.createObjectStore('drafts');};return request(r);}
export function validateBackup(data){if(!data||data.schema!=='snowvalley-browser-backup/1'||!Array.isArray(data.localStorage)||!Array.isArray(data.drafts))throw Error('这不是有效的雪隐山居迁移存档');const keys=new Set();for(const e of data.localStorage){if(!e||!allowedKey(e.key)||typeof e.value!=='string'||keys.has(e.key))throw Error('存档键名、内容或重复条目无效');keys.add(e.key);}const drafts=new Set();for(const e of data.drafts){if(!e||typeof e.key!=='string'||typeof e.value!=='string'||drafts.has(e.key))throw Error('地形备份条目无效');drafts.add(e.key);try{JSON.parse(e.value);}catch{throw Error('地形备份不是完整 JSON');}}return data;}
export async function exportBackup(){const entries=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(allowedKey(key))entries.push({key,value:localStorage.getItem(key)});}const db=await openDB();try{const tx=db.transaction('drafts','readonly'),completed=done(tx),store=tx.objectStore('drafts'),keysRequest=request(store.getAllKeys()),valuesRequest=request(store.getAll()),[keys,values]=await Promise.all([keysRequest,valuesRequest]);await completed;return{schema:'snowvalley-browser-backup/1',exportedAt:new Date().toISOString(),sourceOrigin:location.origin,localStorage:entries,drafts:keys.map((key,i)=>({key,value:values[i]}))};}finally{db.close();}}
// Existing unrelated values are preserved; existing game values are only replaced
// when the user selects the explicit overwrite checkbox.
export async function importBackup(raw,{overwrite=false}={}){const data=validateBackup(raw),db=await openDB();let changed=0,skipped=0;try{const tx=db.transaction('drafts','readonly'),completed=done(tx),oldKeys=await request(tx.objectStore('drafts').getAllKeys());await completed;const existing=new Set(oldKeys),drafts=data.drafts.filter(e=>overwrite||!existing.has(e.key));skipped+=data.drafts.length-drafts.length;
 const selected=data.localStorage.filter(e=>{if(!overwrite&&localStorage.getItem(e.key)!==null){skipped++;return false;}return true;}),old=selected.map(e=>({key:e.key,value:localStorage.getItem(e.key)}));
 try{for(const e of selected)localStorage.setItem(e.key,e.value);const write=db.transaction('drafts','readwrite'),complete=done(write),store=write.objectStore('drafts');for(const e of drafts)store.put(e.value,e.key);await complete;changed=selected.length+drafts.length;}catch(error){for(const e of old){try{localStorage.removeItem(e.key);}catch{}}for(const e of old){try{e.value===null?localStorage.removeItem(e.key):localStorage.setItem(e.key,e.value);}catch{}}throw error;}return{changed,skipped};
 }finally{db.close();}}
